function boot(global,data){
  'use strict';
  const doc=global.document,root=doc.getElementById('a184ExpertDiagnostics');if(!root||root.dataset.ready==='1')return;root.dataset.ready='1';
  const $=id=>doc.getElementById(id),key='nauka-od-a-do-z-fix184-expert-diagnostics-v1';
  const safeParse=(raw,fallback)=>{try{const v=JSON.parse(raw);return v&&typeof v==='object'?v:fallback;}catch(_){return fallback;}};
  const state=safeParse(global.localStorage?.getItem(key),{completed:[],notes:{},caseScores:{},projectChecks:{},examHistory:[],points:0});
  if(!Array.isArray(state.completed))state.completed=[];
  if(!state.notes||typeof state.notes!=='object'||Array.isArray(state.notes))state.notes={};
  if(!state.caseScores||typeof state.caseScores!=='object'||Array.isArray(state.caseScores))state.caseScores={};
  if(!state.projectChecks||typeof state.projectChecks!=='object'||Array.isArray(state.projectChecks))state.projectChecks={};
  if(!Array.isArray(state.examHistory))state.examHistory=[];
  state.points=Number.isFinite(state.points)?state.points:0;
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const save=()=>{try{global.localStorage?.setItem(key,JSON.stringify(state));}catch(_){status('Nie udało się zapisać postępów — wyeksportuj kopię.');}};
  const award=(id,pts,label)=>{const token=`fix184-${id}`;if(state.completed.includes(token))return false;state.completed.push(token);state.points+=pts;try{global.ACADEMY_FIX168_AWARD?.(token,pts,`FIX184 · ${label}`);}catch(_){}save();return true;};
  const status=t=>{const n=$('a184Status');if(n)n.textContent=t;};
  const download=(name,body,type)=>{const blob=new Blob([body],{type}),url=URL.createObjectURL(blob),a=doc.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
  const completed=id=>state.completed.includes(`fix184-lesson-${id}`);
  const category=$('a184Category');[...new Set(data.lessons.map(x=>x.category))].forEach(v=>{const o=doc.createElement('option');o.value=v;o.textContent=v;category?.appendChild(o);});
  let selected=data.lessons[0];
  const progress=()=>{const n=state.completed.filter(x=>x.startsWith('fix184-lesson-')).length,pct=Math.round(n/data.lessons.length*100);$('a184Progress').style.width=`${pct}%`;$('a184LessonsDone').textContent=`${n}/${data.lessons.length}`;$('a184CasesDone').textContent=Object.keys(state.caseScores).filter(k=>state.caseScores[k]===100).length+'/'+data.cases.length;$('a184ProjectsDone').textContent=Object.values(state.projectChecks).filter(x=>Array.isArray(x)&&x.length>=5).length+'/'+data.projects.length;$('a184ExamDone').textContent=state.examHistory.filter(x=>x.passed).length;$('a184Points').textContent=state.points;};
  const renderList=()=>{const term=String($('a184Search')?.value||'').toLocaleLowerCase('pl-PL'),cat=category?.value||'all',lvl=$('a184Level')?.value||'all',items=data.lessons.filter(x=>(cat==='all'||x.category===cat)&&(lvl==='all'||x.level===lvl)&&`${x.title} ${x.summary} ${x.category}`.toLocaleLowerCase('pl-PL').includes(term));const host=$('a184LessonList');host.innerHTML=items.map(x=>`<button type="button" class="a184-lesson ${selected?.id===x.id?'active':''}" data-a184-lesson="${esc(x.id)}"><span>${esc(x.category)} · ${esc(x.level)}</span><b>${esc(x.title)}</b><small>${x.minutes} min · ${completed(x.id)?'ZALICZONA':'DO NAUKI'}</small></button>`).join('')||'<p>Brak lekcji dla tych filtrów.</p>';host.querySelectorAll('[data-a184-lesson]').forEach(b=>b.addEventListener('click',()=>{selected=data.lessons.find(x=>x.id===b.dataset.a184Lesson)||data.lessons[0];renderLesson();renderList();}));};
  const renderLesson=()=>{const h=$('a184LessonDetail');if(!h||!selected)return;h.innerHTML=`<header class="a184-detail-head"><div><span>${esc(selected.category)} · ${esc(selected.level)}</span><h3>${esc(selected.title)}</h3><p>${esc(selected.summary)}</p></div><b>${selected.minutes} MIN</b></header><div class="a184-columns"><section><h4>Cele nauki</h4><ul>${selected.goals.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h4>Wyjaśnienie techniczne</h4>${selected.theory.map(x=>`<p>${esc(x)}</p>`).join('')}<h4>Procedura serwisowa</h4><ol>${selected.workflow.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><h4>Ostrzeżenia i ograniczenia</h4><ul class="a184-warn">${selected.cautions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="a184-sources"><h4>Dokumentacja techniczna</h4>${selected.sources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.label)} ↗</a>`).join('')}</div></section><aside class="a184-note"><h4>Notatki do lekcji</h4><textarea id="a184Note" maxlength="5000" placeholder="Notatki bez haseł i danych klienta…">${esc(state.notes[selected.id]||'')}</textarea><button type="button" class="a168-btn" id="a184SaveNote">Zapisz notatkę</button><p>Postępy FIX184 są zapisywane osobno od FIX179–FIX183.</p></aside></div><section class="a184-quiz"><h4>Sprawdź wiedzę — 3 pytania</h4>${selected.quiz.map((x,i)=>`<fieldset><legend>${i+1}. ${esc(x.q)}</legend>${x.a.map((a,j)=>`<label><input type="radio" name="a184q${i}" value="${j}"><span>${esc(a)}</span></label>`).join('')}<p hidden id="a184Why${i}"></p></fieldset>`).join('')}<button type="button" class="a168-btn primary" id="a184CheckQuiz">Sprawdź odpowiedzi</button><p class="a184-result" id="a184QuizResult">Zaliczenie wymaga 2/3 poprawnych odpowiedzi.</p></section>`;
    $('a184SaveNote')?.addEventListener('click',()=>{state.notes[selected.id]=$('a184Note').value;save();status('Notatka FIX184 zapisana.');});
    $('a184CheckQuiz')?.addEventListener('click',()=>{let score=0,answered=0;selected.quiz.forEach((x,i)=>{const choice=h.querySelector(`input[name="a184q${i}"]:checked`);if(choice)answered++;const ok=choice&&Number(choice.value)===x.c;if(ok)score++;const p=$('a184Why'+i);p.hidden=false;p.className=ok?'good':'bad';p.textContent=`${ok?'Poprawnie.':'Niepoprawnie.'} ${x.e}`;});if(answered<selected.quiz.length){$('a184QuizResult').textContent=`Uzupełnij wszystkie pytania (${answered}/${selected.quiz.length}).`;return;}if(score>=2)award(`lesson-${selected.id}`,25,selected.title);$('a184QuizResult').textContent=`Wynik ${score}/3. ${score>=2?'Lekcja zaliczona.':'Przeczytaj wyjaśnienia i spróbuj ponownie.'}`;renderList();progress();});
  };
  const caseSelect=$('a184CaseSelect');caseSelect.innerHTML=data.cases.map((x,i)=>`<option value="${i}">${esc(x.category)} — ${esc(x.title)}</option>`).join('');let activeCase=data.cases[0];
  const renderCase=()=>{const h=$('a184CaseBody');if(!h)return;h.innerHTML=`<span class="a184-domain">${esc(activeCase.category)}</span><h3>${esc(activeCase.title)}</h3><p>${esc(activeCase.symptom)}</p>${activeCase.stages.map((s,i)=>`<fieldset><legend>${esc(s[0])}</legend><select id="a184Stage${i}"><option value="">Wybierz decyzję…</option>${s[1].map((v,j)=>`<option value="${j}">${esc(v)}</option>`).join('')}</select><p hidden id="a184StageWhy${i}"></p></fieldset>`).join('')}<button type="button" class="a168-btn primary" id="a184EvaluateCase">Oceń przypadek</button><p class="a184-result" id="a184CaseResult">Wybierz trzy decyzje.</p>`;h.querySelector('#a184EvaluateCase')?.addEventListener('click',()=>{const vals=activeCase.stages.map((s,i)=>$('a184Stage'+i).value);if(vals.some(x=>x==='')){$('a184CaseResult').textContent='Uzupełnij wszystkie etapy.';return;}let score=0;activeCase.stages.forEach((s,i)=>{const ok=Number(vals[i])===s[2];if(ok)score++;const p=$('a184StageWhy'+i);p.hidden=false;p.className=ok?'good':'bad';p.textContent=`${ok?'Poprawnie.':'Niepoprawnie.'} ${s[3]}`;});const pct=Math.round(score/3*100);state.caseScores[activeCase.id]=Math.max(state.caseScores[activeCase.id]||0,pct);if(pct===100)award(`case-${activeCase.id}`,35,activeCase.title);save();$('a184CaseResult').textContent=`Wynik ${score}/3 (${pct}%).`;progress();});};
  caseSelect.addEventListener('change',()=>{activeCase=data.cases[Number(caseSelect.value)]||data.cases[0];renderCase();});renderCase();
  const renderProjects=()=>{const h=$('a184Projects');h.innerHTML=data.projects.map(p=>{const done=state.projectChecks[p.id]||[];return`<article class="a184-project"><span>${esc(p.category)}</span><h3>${esc(p.title)}</h3>${p.tasks.map((t,i)=>`<label><input type="checkbox" data-a184-project="${esc(p.id)}" data-step="${i}" ${done.includes(i)?'checked':''}><span>${esc(t)}</span></label>`).join('')}<p><b>Rezultat:</b> ${esc(p.deliverable)}</p><small>${done.length}/${p.tasks.length} etapów</small></article>`;}).join('');h.querySelectorAll('[data-a184-project]').forEach(input=>input.addEventListener('change',()=>{const p=data.projects.find(x=>x.id===input.dataset.a184Project),set=new Set(state.projectChecks[p.id]||[]),step=Number(input.dataset.step);input.checked?set.add(step):set.delete(step);state.projectChecks[p.id]=[...set].sort((a,b)=>a-b);if(set.size===p.tasks.length)award(`project-${p.id}`,50,p.title);save();renderProjects();progress();}));};renderProjects();
  const renderGlossary=()=>{const h=$('a184Glossary'),term=String($('a184GlossarySearch')?.value||'').toLocaleLowerCase('pl-PL'),rows=data.glossary.filter(([a,b])=>`${a} ${b}`.toLocaleLowerCase('pl-PL').includes(term));h.innerHTML=rows.map(([a,b])=>`<article><b>${esc(a)}</b><span>${esc(b)}</span></article>`).join('')||'<p>Brak terminu.</p>';};$('a184GlossarySearch')?.addEventListener('input',renderGlossary);renderGlossary();
  const examHost=$('a184Exam');examHost.innerHTML=`<p>Egzamin FIX184 — ${data.exam.length} pytań, próg zaliczenia 80%. Wewnętrzne ćwiczenie szkoleniowe.</p>${data.exam.map((x,i)=>`<fieldset><legend>${i+1}. ${esc(x.q)}</legend>${x.a.map((a,j)=>`<label><input type="radio" name="a184exam${i}" value="${j}"><span>${esc(a)}</span></label>`).join('')}<p hidden id="a184ExamWhy${i}"></p></fieldset>`).join('')}<button type="button" class="a168-btn primary" id="a184SubmitExam">Zakończ egzamin</button><p id="a184ExamResult" class="a184-result">Odpowiedz na wszystkie pytania.</p><div id="a184ExamHistory"></div>`;
  const renderExamHistory=()=>{$('a184ExamHistory').innerHTML=state.examHistory.slice(0,8).map(x=>`<p>${new Date(x.at).toLocaleString('pl-PL')} — ${x.score}/${x.total} (${x.pct}%) · ${x.passed?'ZALICZONY':'NIEZALICZONY'}</p>`).join('');};
  $('a184SubmitExam').addEventListener('click',()=>{let score=0,answered=0;data.exam.forEach((x,i)=>{const c=examHost.querySelector(`input[name="a184exam${i}"]:checked`);if(c)answered++;const ok=c&&Number(c.value)===x.c;if(ok)score++;const p=$('a184ExamWhy'+i);p.hidden=false;p.className=ok?'good':'bad';p.textContent=`${ok?'Poprawnie.':'Niepoprawnie.'} ${x.e}`;});if(answered<data.exam.length){$('a184ExamResult').textContent=`Odpowiedz na wszystkie pytania (${answered}/${data.exam.length}).`;return;}const pct=Math.round(score/data.exam.length*100),passed=pct>=80;state.examHistory.unshift({at:new Date().toISOString(),score,total:data.exam.length,pct,passed});state.examHistory=state.examHistory.slice(0,50);if(passed)award('expert-exam',100,'Egzamin FIX184');save();$('a184ExamResult').textContent=`Wynik ${score}/${data.exam.length} (${pct}%). ${passed?'Egzamin zaliczony.':'Próg to 80% — ponów próbę.'}`;renderExamHistory();progress();});renderExamHistory();
  // Read-only PowerShell report generator. It displays a template; it never executes it.
  const psAreas=['system','bios','cpu','memory','disks','events','network'];
  const renderPs=()=>{const picked=psAreas.filter(x=>$(`a184Ps_${x}`)?.checked),lines=["$ErrorActionPreference = 'Stop'","$ProgressPreference = 'SilentlyContinue'","$Report = [ordered]@{}","$Report.CollectedAtUtc = (Get-Date).ToUniversalTime().ToString('o')"];
    const map={system:["$Report.Computer = Get-CimInstance Win32_ComputerSystem | Select-Object Manufacturer, Model, Domain, NumberOfLogicalProcessors","$Report.OS = Get-CimInstance Win32_OperatingSystem | Select-Object Caption, Version, BuildNumber, LastBootUpTime"],bios:["$Report.BIOS = Get-CimInstance Win32_BIOS | Select-Object Manufacturer, SMBIOSBIOSVersion, ReleaseDate"],cpu:["$Report.CPU = Get-CimInstance Win32_Processor | Select-Object Name, NumberOfCores, NumberOfLogicalProcessors"],memory:["$Report.Memory = Get-CimInstance Win32_PhysicalMemory | Select-Object Capacity, Speed, ConfiguredClockSpeed, Manufacturer"],disks:["$Report.Disks = Get-CimInstance Win32_DiskDrive | Select-Object Model, InterfaceType, Size, Status"],events:["$Since = (Get-Date).AddDays(-2)","$Report.SystemEvents = Get-WinEvent -FilterHashtable @{LogName='System'; StartTime=$Since} -MaxEvents 200 | Select-Object TimeCreated, Id, LevelDisplayName, ProviderName, Message"],network:["$Report.Network = Get-CimInstance Win32_NetworkAdapterConfiguration -Filter 'IPEnabled=True' | Select-Object Description, DHCPEnabled, IPAddress, DNSServerSearchOrder"]};picked.forEach(x=>lines.push(...(map[x]||[])));lines.push("$Report | ConvertTo-Json -Depth 5");const out=$('a184PsScript');out.textContent=picked.length?lines.join('\n'):'Zaznacz co najmniej jedną sekcję raportu.';$('a184PsStatus').textContent=picked.length?`Przygotowano szablon tylko do odczytu (${picked.length} sekcji). Nic nie zostało uruchomione.`:'Wybierz zakres raportu.';};
  root.querySelectorAll('[data-a184-ps]').forEach(x=>x.addEventListener('change',renderPs));$('a184PsBuild')?.addEventListener('click',renderPs);renderPs();
  const fillSelect=(id,items)=>{const sel=$(id);sel.innerHTML=items.map(([v,l])=>`<option value="${esc(v)}">${esc(l)}</option>`).join('');};
  fillSelect('a184DomainScenario',Object.entries(data.tools.domain).map(([k,v])=>[k,v.label]));const showDomain=()=>{const s=data.tools.domain[$('a184DomainScenario').value];$('a184DomainOutput').innerHTML=`<b>${esc(s.label)}</b><ol>${s.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><p class="a184-warning">${esc(s.warning)}</p>`;};$('a184DomainScenario').addEventListener('change',showDomain);showDomain();
  fillSelect('a184DbgScenario',Object.entries(data.tools.windbg).map(([k,v])=>[k,v.label]));const showDbg=()=>{const s=data.tools.windbg[$('a184DbgScenario').value];$('a184DbgOutput').innerHTML=`<b>${esc(s.label)}</b><p>Przykładowe polecenia do analizy kopii dumpa:</p><code>${s.commands.map(esc).join('<br>')}</code><ol>${s.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>`;};$('a184DbgScenario').addEventListener('change',showDbg);showDbg();
  fillSelect('a184RemoteScenario',Object.entries(data.tools.remote).map(([k,v])=>[k,v.label]));const showRemote=()=>{const s=data.tools.remote[$('a184RemoteScenario').value];$('a184RemoteOutput').innerHTML=`<b>${esc(s.label)}</b><ol>${s.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><p class="a184-warning">${esc(s.security)}</p>`;};$('a184RemoteScenario').addEventListener('change',showRemote);showRemote();
  const calcSignal=()=>{const z0=Number($('a184Z0').value),zl=Number($('a184ZL').value),rate=Number($('a184Rate').value),tr=Number($('a184Rise').value);const h=$('a184SignalOutput');if(!(z0>0&&zl>0&&rate>0&&tr>0&&z0<10000&&zl<10000&&rate<1000&&tr<100000)){h.textContent='Wprowadź dodatnie, realistyczne wartości impedancji, szybkości i czasu narastania.';return;}const gamma=(zl-z0)/(zl+z0),mag=Math.abs(gamma),rl=mag===0?Infinity:-20*Math.log10(mag),ui=1000/rate,ratio=tr/ui*100;h.innerHTML=`<b>Współczynnik odbicia Γ: ${gamma.toFixed(4)}</b><p>Moduł odbicia: ${(mag*100).toFixed(2)}% wartości amplitudy incydentnej.</p><p>Return Loss: ${Number.isFinite(rl)?rl.toFixed(2)+' dB':'teoretycznie nieskończony dla Γ = 0'}.</p><p>Jednostka czasu UI: ${ui.toFixed(3)} ps przy ${rate} Gb/s.</p><p>Czas narastania / UI: ${ratio.toFixed(1)}%.</p><p class="a184-warning">Model idealnego pojedynczego skoku. Nie ocenia zgodności PCIe/USB i nie zastępuje kalibrowanego TDR/VNA ani maski oka.</p>`;};$('a184SignalCalc').addEventListener('click',calcSignal);calcSignal();
  $('a184GlossarySearch')?.addEventListener('input',renderGlossary);
  $('a184Export')?.addEventListener('click',()=>download('Kopia_Postepow_FIX184.json',JSON.stringify({fix:184,productVersion:data.version,exportedAt:new Date().toISOString(),state},null,2),'application/json;charset=utf-8'));
  $('a184Report')?.addEventListener('click',()=>download('Raport_Szkolenia_FIX184.json',JSON.stringify({fix:184,productVersion:data.version,generatedAt:new Date().toISOString(),lessons:data.lessons.length,completed:state.completed,cases:data.cases.length,caseScores:state.caseScores,projects:data.projects.length,projectChecks:state.projectChecks,examHistory:state.examHistory,points:state.points,trainingOnly:true},null,2),'application/json;charset=utf-8'));
  renderList();renderLesson();progress();status(`FIX184 gotowy: ${data.lessons.length} lekcji, ${data.cases.length} przypadków, ${data.projects.length} projektów, ${data.exam.length} pytań i ${data.glossary.length} terminów.`);
}
